import React from "react";

function Footer() {
  return (
    <footer className="bg-blue-900 text-white py-8 mt-auto">
      <div className="container mx-auto px-6 text-center md:text-left grid md:grid-cols-2 gap-6">
        <div>
          <h3 className="text-xl font-bold mb-2">Luminos</h3>
          <p>Enterprise Claims Management Platform by Gallagher Bassett.</p>
        </div>
        <div className="space-y-2">
          <a href="#features" className="block hover:underline">Features</a>
          <a href="#demo" className="block hover:underline">Book a Demo</a>
          <a href="#contact" className="block hover:underline">Contact</a>
        </div>
      </div>
      <div className="text-center text-sm mt-6 text-gray-300">
        © {new Date().getFullYear()} Luminos. All rights reserved.
      </div>
    </footer>
  );
}

export default Footer;
